mutation removeLineItemFromCart($cartId: String!, $lineItemId: String!, $version: Long!, $quantity: Long!, $locale: Locale!) {
  updateMyCart(
    id: $cartId
    actions: {removeLineItem: {lineItemId: $lineItemId, quantity: $quantity}}
    version: $version
  ) {
    id
    version
    isAbleToCheckout
    isRestricted
    isHazardous
    isEmpty
    isDangerous
    splittableSupplyChannelKeys
    isSplit
    discountedPrice {
      centAmount
      currencyCode
      fractionDigits
    }
    customerGroup {
      key
    }
    lineItems {
      ...defaultLineItem
    }
    totalLineItemQuantity
    totalPrice {
      centAmount
      currencyCode
      fractionDigits
    }
  }
}

