query ShopProductSearch(
                  $brokerId: ID!
                  $first: Int!
                  $after: String
                  $filter: [SearchFilterV2!]
                  $sortBy: ShopProductSearchSortByV2
                  $query: String
                  $searchKind: SearchKind!
                  $includeProductFilters: Boolean!
                ) {
                  shopProductSearch(
                    brokerId: $brokerId
                    first: $first
                    after: $after
                    filter: $filter
                    sortBy: $sortBy
                    query: $query
                  ) {
                    ...ProductSearch
                    __typename
                  }
                  productFilters(query: $query, shopId: $brokerId, searchKind: $searchKind)
                    @include(if: $includeProductFilters) {
                    ...ProductFilter
                    __typename
                  }
                }

                fragment ProductSearch on ProductSearchConnection {
                  nodes {
                    __typename
                    id
                    ... on DiscoveryProduct {
                      id
                      ...ProductCard
                      __typename
                    }
                  }
                  pageInfo {
                    hasNextPage
                    endCursor
                    __typename
                  }
                  filter {
                    network
                    __typename
                  }
                  inferredCategoryFilters
                  totalCount
                  totalCountCapped
                  inferredQueryType
                  __typename
                }

                fragment ProductFilter on ProductFilter {
                  key
                  defaultValue
                  value
                  configurations {
                    __typename
                    ... on ProductFilterSheetConfiguration {
                      __typename
                      title
                      icon
                      screenTitle
                      filterKind
                      position
                      refreshOnUpdate
                      refreshOptionsOnUpdate
                      options {
                        accessibilityLabel
                        configuration
                        icon
                        label
                        value
                        __typename
                      }
                    }
                    ... on ProductFilterPillConfiguration {
                      __typename
                      title
                      icon
                      screenTitle
                      filterKind
                      position
                      options {
                        accessibilityLabel
                        configuration
                        icon
                        label
                        value
                        __typename
                      }
                    }
                    ... on ProductFilterChipConfiguration {
                      __typename
                      title
                      icon
                      screenTitle
                      filterKind
                      position
                      options {
                        accessibilityLabel
                        configuration
                        icon
                        label
                        value
                        __typename
                      }
                    }
                  }
                  __typename
                }

                fragment ProductCard on DiscoveryProduct {
                  id
                  title
                  inDefaultProductList
                  isProductDiscoveryEligible
                  defaultVariantId
                  shareUrl
                  offers {
                    id
                    ... on AutomaticDiscount {
                      ...AutomaticDiscount
                      __typename
                    }
                    __typename
                  }
                  price {
                    amount
                    currencyCode
                    __typename
                  }
                  originalPrice {
                    amount
                    currencyCode
                    __typename
                  }
                  url
                  images {
                    ...ReducedImage
                    __typename
                  }
                  reviewAnalytics {
                    averageRating
                    count
                    __typename
                  }
                  shop {
                    id
                    name
                    nativeProductPagesEnabled
                    shopifyId
                    followedByMe
                    __typename
                  }
                  supportsSimilaritySearch
                  shopCashOffer {
                    id
                    __typename
                  }
                  __typename
                }

                fragment AutomaticDiscount on AutomaticDiscount {
                  id
                  constraints {
                    text
                    type
                    __typename
                  }
                  description
                  shortDescription
                  discountAmount {
                    ...MoneyV2Fragment
                    __typename
                  }
                  discountClass
                  discountPercentage
                  discountType
                  minimumRequirementAmount {
                    ...MoneyV2Fragment
                    __typename
                  }
                  minimumRequirementQuantity
                  minimumRequirementType
                  __typename
                }

                fragment ReducedImage on Image {
                  url
                  altText
                  height
                  width
                  __typename
                }

                fragment MoneyV2Fragment on MoneyV2 {
                  amount
                  currencyCode
                  __typename
                }

