query fetchOrderConfirmation($stripePaymentIntentId: String!, $locale: Locale!, $preferredLocale: Locale) {
  fetchOrderConfirmation(stripePaymentIntentId: $stripePaymentIntentId) {
    id
    country
    customerId
    customerEmail
    orderNumber
    paymentMethodName
    discountOnTotalPrice {
      includedDiscounts {
        discount {
          id
          description(locale: $locale)
          fallbackDescription: description(locale: en)
          name(locale: $locale)
          fallbackName: name(locale: en)
          requiresDiscountCode
          __typename
        }
        discountedAmount {
          ...MoneyFragment
          __typename
        }
        __typename
      }
      __typename
    }
    lineItems {
      ...LineItemFragment_Cart
      __typename
    }
    shippingAddress {
      ...AddressFragment
      __typename
    }
    discountCodes {
      ...DiscountCodeFragment
      __typename
    }
    shippingInfo {
      shippingMethodName
      price {
        ...MoneyFragment
        __typename
      }
      taxRate {
        includedInPrice
        __typename
      }
      discountedPrice {
        value {
          ... on Money {
            ...MoneyFragment
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    totalPrice {
      ...MoneyFragment
      __typename
    }
    taxedPrice {
      totalNet {
        ...MoneyFragment
        __typename
      }
      totalGross {
        ...MoneyFragment
        __typename
      }
      __typename
    }
    __typename
  }
}

