    name
    __typename
  }
  category(locale: $locale)
  price {
    ...ProductPriceFragment
    __typename
  }
  mainImage {
    ...ImageAssetFragment
    __typename
  }
  variant {
    availability {
      noChannel {
        availableQuantity
        expectedDelivery
        __typename
      }
      __typename
    }
    brands {
      name
      value
      __typename
    }
    campaignId
    campaignSlug
