    id
    name(locale: $locale)
    namePreferred: name(locale: $preferredLocale)
    nameFallback: name(locale: $fallbackLocale)
    __typename
  }
  mainImage {
    ...ImageAssetFragment
    __typename
  }
  variants {
    sku
    id
    availability {
      noChannel {
        availableQuantity
        expectedDelivery
        __typename
      }
      __typename
    }
    attributesRaw {
      ...AttributesRawFragment
      __typename
    }
    __typename
  }
  brands {
    ...ProductBrandFragment
    __typename
  }
  masterVariant {
    ...ProductVariantFragment
    __typename
  }
  editorsNotesText(locale: $locale) {
    ...StructuredTextContentFragment
    __typename
  }
  editorsNotesTextPreferred: editorsNotesText(locale: $preferredLocale) {
