    __typename
  }
  sizeAndFitTextTextPreferred: sizeAndFitText(locale: $preferredLocale) {
    ...StructuredTextContentFragment
    __typename
  }
  sizeAndFitTextTextFallback: sizeAndFitText(locale: $fallbackLocale) {
    ...StructuredTextContentFragment
    __typename
  }
  styleProducts {
    ...StyleProductsFragment
    __typename
  }
  __typename
