  inStore(key: $key) {
    me {
      activeCart {
        ...defaultCart
      }
    }
  }
}

fragment defaultCart on Cart {
  id
  version
  locale
  isAbleToCheckout
  isRestricted
  isHazardous
  isEmpty
  isDangerous
  splittableSupplyChannelKeys
  isSplit
  shippingMode
  totalLineItemQuantity
  anonymousId
  customerId
  whPlusOnly
  customerEmail
  customer {
    ...defaultCustomer
  }
  billingAddress {
    ...defaultAddress
  }
  paymentInfo {
    payments {
      amountPlanned {
        type
        currencyCode
        centAmount
        fractionDigits
      }
      paymentMethodInfo {
        method
      }
      id
      version
      custom {
        customFieldsRaw {
          name
          value
        }
      }
    }
  }
  shipping {
    ...defaultShipping
  }
  customerGroup {
    key
  }
  lineItems {
    ...defaultLineItem
  }
  itemShippingAddresses {
    ...defaultAddress
  }
  discountedPrice {
    centAmount
    currencyCode
    fractionDigits
  }
  totalPrice {
    centAmount
    currencyCode
    fractionDigits
  }
  taxedPrice {
    totalTax {
      centAmount
      currencyCode
      fractionDigits
    }
    totalGross {
      centAmount
      currencyCode
      fractionDigits
    }
    taxPortions {
      name
      amount {
        centAmount
        currencyCode
        fractionDigits
      }
    }
  }
  custom {
    customFieldsRaw {
      name
      value
    }
  }
