}

fragment defaultAddress on Address {
  isDefault
  id
  key
  streetName
  streetNumber
  additionalStreetInfo
  city
  postalCode
  region
  state
  country
  firstName
  lastName
  email
  phone
  externalId
  custom {
    customFieldsRaw {
      name
      value
    }
  }
}

fragment defaultShipping on Shipping {
  shippingKey
  shippingInfo {
    isHazardous
    deliveries {
      id
      items {
        id
        quantity
      }
    }
    price {
      centAmount
      currencyCode
      fractionDigits
    }
    shippingMethodName
    shippingMethod {
      localizedName(locale: $locale)
    }
  }
  shippingAddress {
    ...defaultAddress
  }
  isValid
}

fragment defaultLineItem on LineItem {
  id
  productId
  productSlug(locale: $locale)
  name(locale: $locale)
  productType {
    id
    version
    name
  }
  totalPrice {
    centAmount
    currencyCode
    fractionDigits
  }
  preDiscountedPrice {
    centAmount
    currencyCode
    fractionDigits
  }
  shippingDetails {
    targets {
      addressKey
      shippingMethodKey
      quantity
    }
    valid
  }
  productKey
  quantity
  variant {
    sku
    key
    images {
      url
    }
    attributesRaw {
      name
      value
    }
  }
  discountedPricePerQuantity {
    discountedPrice {
      includedDiscounts {
        discount {
          id
          key
          description(locale: $locale)
        }
      }
    }
  }
  custom {
    customFieldsRaw {
      name
      value
    }
  }
  supplyChannel {
    id
    key
  }
  lineItemMode
}

